//! What the code generated by `#[scheduling]` and `#[retryable]` calls. Not a public API: the
//! items are reachable as `oxbloom_tasks::__private` only so that the generated code can name
//! them.

use std::fmt;
use std::future::Future;
use std::time::Duration;

use crate::retry::{Backoff, Jitter, RetryDefaults, RetryPolicy, defaults};

use crate::task::{BoxFuture, Task};
use crate::trigger::{Trigger, TriggerError, Zone, parse_duration};

/// The trigger of one `#[scheduled]` method, as the string literals of its attribute.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Spec {
    /// `cron = ".."`, with `zone = ".."` when given (`None`: the scheduler's zone).
    Cron(&'static str, Option<&'static str>),
    /// `fixed_rate = ".."`.
    FixedRate(&'static str),
    /// `fixed_delay = ".."`.
    FixedDelay(&'static str),
}

impl Spec {
    /// Parses the literals into a trigger, or names the key whose value is invalid.
    fn trigger(self) -> Result<Trigger, (&'static str, TriggerError)> {
        let duration = |key, text| parse_duration(text).map_err(|error| (key, error));
        match self {
            // Without `zone` the trigger keeps the default zone, which the scheduler fills
            // with `SchedulerConfig::zone` (`tasks.scheduling.zone`).
            Spec::Cron(expression, None) => {
                Trigger::cron_in_default_zone(expression).map_err(|error| ("cron", error))
            }
            Spec::Cron(expression, Some(name)) => {
                let zone = Zone::parse(name).map_err(|error| ("zone", error))?;
                Trigger::cron(expression, zone).map_err(|error| ("cron", error))
            }
            Spec::FixedRate(text) => Trigger::fixed_rate(duration("fixed_rate", text)?)
                .map_err(|error| ("fixed_rate", error)),
            Spec::FixedDelay(text) => Trigger::fixed_delay(duration("fixed_delay", text)?)
                .map_err(|error| ("fixed_delay", error)),
        }
    }
}

/// Builds the task of one `#[scheduled]` method. A literal that does not parse gives
/// [`Task::invalid`] with its key, so the scheduler refuses to start and names both.
pub fn task<F>(name: String, spec: Spec, initial_delay: Option<&'static str>, run: F) -> Task
where
    F: Fn() -> BoxFuture<'static, Result<(), String>> + Send + Sync + 'static,
{
    let delay = initial_delay
        .map(parse_duration)
        .transpose()
        .map_err(|error| ("initial_delay", error));
    match (spec.trigger(), delay) {
        (Err((key, error)), _) | (Ok(_), Err((key, error))) => Task::invalid(name, key, error),
        (Ok(trigger), Ok(delay)) => {
            let task = Task::new(name, trigger, run);
            match delay {
                Some(delay) => task.initial_delay(delay),
                None => task,
            }
        }
    }
}

/// Runs the body of a plain `fn` method on tokio's blocking pool. A panic in it is raised
/// again in the returned future, so the scheduler records the run as panicked.
pub fn blocking<F>(body: F) -> BoxFuture<'static, Result<(), String>>
where
    F: FnOnce() -> Result<(), String> + Send + 'static,
{
    Box::pin(async move {
        match tokio::task::spawn_blocking(body).await {
            Ok(result) => result,
            Err(error) if error.is_panic() => std::panic::resume_unwind(error.into_panic()),
            Err(_) => Err("the blocking task was cancelled".to_owned()),
        }
    })
}

/// The return types a `#[scheduled]` method may have: `()` and `Result<(), E>` where
/// `E: Display`.
pub trait RunResult {
    /// The outcome of the run, with the error as its [`Display`](fmt::Display) string.
    fn into_run_result(self) -> Result<(), String>;
}

impl RunResult for () {
    fn into_run_result(self) -> Result<(), String> {
        Ok(())
    }
}

impl<E: fmt::Display> RunResult for Result<(), E> {
    fn into_run_result(self) -> Result<(), String> {
        self.map_err(|error| error.to_string())
    }
}

/// The fields that one `#[retryable(..)]` attribute fixes; `None` takes the value of
/// [`defaults`](crate::defaults) when the method is called. Durations are in milliseconds.
///
/// # Examples
///
/// ```
/// use oxbloom_tasks::__private::Overrides;
///
/// let overrides = Overrides { max_attempts: Some(5), ..Overrides::NONE };
/// assert_eq!(overrides.backoff, None);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Overrides {
    /// `max_attempts = ..`.
    pub max_attempts: Option<u32>,
    /// `backoff = ".."`.
    pub backoff: Option<Backoff>,
    /// `initial = ".."`, in milliseconds.
    pub initial_millis: Option<u64>,
    /// `multiplier = ..`.
    pub multiplier: Option<f64>,
    /// `max_delay = ".."`, in milliseconds.
    pub max_delay_millis: Option<u64>,
    /// `jitter = ".."`.
    pub jitter: Option<Jitter>,
}

impl Overrides {
    /// No field fixed: every value comes from the defaults.
    pub const NONE: Overrides = Overrides {
        max_attempts: None,
        backoff: None,
        initial_millis: None,
        multiplier: None,
        max_delay_millis: None,
        jitter: None,
    };

    /// The policy of `defaults` with these fields replaced.
    fn policy(self, defaults: RetryDefaults) -> RetryPolicy {
        RetryPolicy {
            max_attempts: self.max_attempts.unwrap_or(defaults.max_attempts),
            backoff: self.backoff.unwrap_or(defaults.backoff),
            initial: self
                .initial_millis
                .map_or(defaults.initial, Duration::from_millis),
            multiplier: self.multiplier.unwrap_or(defaults.multiplier),
            max_delay: self
                .max_delay_millis
                .map_or(defaults.max_delay, Duration::from_millis),
            jitter: self.jitter.unwrap_or(defaults.jitter),
        }
    }
}

/// A value of any type, for the branch of the code generated by `#[retryable]` that is never
/// taken: `if false { return never::<R>(); }` fixes the output type of the generated `async`
/// block to the method's return type `R`, so the body keeps the coercions of a normal method.
///
/// # Panics
///
/// Always; the generated code never calls it.
///
/// # Examples
///
/// ```
/// use oxbloom_tasks::__private::never;
///
/// async fn name(text: &String) -> Result<&str, std::io::Error> {
///     let output = async {
///         if false {
///             return never::<Result<&str, std::io::Error>>();
///         }
///         Ok(text)
///     };
///     output.await
/// }
/// # let _ = name;
/// ```
#[track_caller]
pub fn never<R>() -> R {
    unreachable!("the output type branch of #[retryable] is never taken")
}

/// Runs the body of one `#[retryable]` method: builds the policy from
/// [`defaults`](crate::defaults) with `overrides` applied when the returned future is first
/// polled, then calls [`RetryPolicy::run`] with the method name as `label`.
///
/// # Examples
///
/// ```
/// use oxbloom_tasks::__private::{Overrides, retry_call};
///
/// # tokio::runtime::Builder::new_current_thread().enable_all().start_paused(true).build()?.block_on(async {
/// let overrides = Overrides { max_attempts: Some(2), ..Overrides::NONE };
/// let result: Result<(), &str> = retry_call("fetch", overrides, |_| true, || async { Err("down") }).await;
/// assert_eq!(result, Err("down"));
/// # });
/// # Ok::<(), std::io::Error>(())
/// ```
pub async fn retry_call<T, E, Fut, Op, If>(
    label: &'static str,
    overrides: Overrides,
    retry_if: If,
    op: Op,
) -> Result<T, E>
where
    Op: FnMut() -> Fut,
    Fut: Future<Output = Result<T, E>>,
    E: fmt::Display,
    If: Fn(&E) -> bool,
{
    overrides.policy(defaults()).run(label, op, retry_if).await
}
